const BASE = process.env.BASE ?? 'http://127.0.0.1:3100'
const VIEWPORT = { width: 1440, height: 900 }

const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: VIEWPORT })
const page = await ctx.newPage()

const started = new Map()
const finished = []
page.on('request', (r) => {
  if (r.url().includes('/_next/image')) started.set(r.url(), Date.now())
})
page.on('requestfinished', (r) => {
  if (r.url().includes('/_next/image')) {
    finished.push({ url: r.url(), ms: Date.now() - started.get(r.url()) })
  }
})
page.on('requestfailed', (r) => {
  if (r.url().includes('/_next/image')) {
    finished.push({ url: r.url(), ms: Date.now() - started.get(r.url()), failed: true })
  }
})

