import { chromium } from '@playwright/test'

const BASE = 'http://localhost:3000'
const browser = await chromium.launch()

// --- first-paint optimiser count at the three review viewports ---
for (const vp of [
  { width: 390, height: 844, name: 'phone' },
  { width: 834, height: 1112, name: 'tablet' },
  { width: 1440, height: 900, name: 'desktop' },
  { width: 1440, height: 2000, name: 'tall desktop' },
]) {
  const ctx = await browser.newContext({ viewport: { width: vp.width, height: vp.height } })
  const page = await ctx.newPage()
  const reqs = new Set()
  page.on('request', (r) => { if (r.url().includes('/_next/image')) reqs.add(r.url()) })
  await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(3000)
  const aboveFoldGrey = await page.evaluate(() =>
    [...document.querySelectorAll('a[href^="/products/"] > div > div')].filter((box) => {
      const r = box.getBoundingClientRect()
      const onScreen = r.top < window.innerHeight && r.bottom > 0
      const img = box.querySelector('img')
      return onScreen && (!img || !(img as HTMLImageElement).complete || (img as HTMLImageElement).naturalWidth === 0)
    }).length,
  )
  console.log(`${vp.name.padEnd(13)} ${String(vp.width).padStart(4)}x${vp.height}: ${String(reqs.size).padStart(2)} optimiser requests, ${aboveFoldGrey} above-fold boxes still empty`)
  await ctx.close()
}

// --- measured contrast of the placeholder against both band colours ---
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const page = await ctx.newPage()
await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' })
const contrast = await page.evaluate(() => {
  const lum = (rgb) => {
    const [r, g, b] = rgb.match(/\d+/g).slice(0, 3).map(Number).map((v) => {
      const c = v / 255
      return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)
    })
    return 0.2126 * r + 0.7152 * g + 0.0722 * b
  }
  const ratio = (a, b) => {
    const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x)
    return ((hi + 0.05) / (lo + 0.05)).toFixed(3)
  }
  const boxes = [...document.querySelectorAll('a[href^="/products/"] > div > div')]
  const placeholder = getComputedStyle(boxes[0]).backgroundColor
  // Walk up to the Block outer for each of the two alternating bands.
  const bands = [...document.querySelectorAll('main > div')].slice(2, 4).map((el) => {
    let node = el
    let bg = getComputedStyle(node).backgroundColor
    while (bg === 'rgba(0, 0, 0, 0)' && node.parentElement) {
      node = node.parentElement
      bg = getComputedStyle(node).backgroundColor
    }
    return bg
  })
  return {
    placeholder,
    bands,
    ratios: bands.map((b) => ratio(placeholder, b)),
  }
})
console.log(`\nplaceholder ${contrast.placeholder}`)
contrast.bands.forEach((b, i) => console.log(`  vs band ${i + 1} ${b}: ${contrast.ratios[i]}:1`))

await browser.close()

