import { chromium } from '@playwright/test'

const BASE = 'http://localhost:3000'
const browser = await chromium.launch()

/**
 * Resolve any CSS colour to sRGB by making the browser paint it. Tailwind 4
 * serialises these as `lab()`, and a regex for numbers reads those components
 * as if they were RGB -- the trap AGENTS.md names explicitly.
 */
const RESOLVE = `(css) => {
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = 1
  const ctx = canvas.getContext('2d')
  ctx.fillStyle = css
  ctx.fillRect(0, 0, 1, 1)
  return [...ctx.getImageData(0, 0, 1, 1).data].slice(0, 3)
}`

for (const vp of [
  { width: 390, height: 844, name: 'phone' },
  { width: 834, height: 1112, name: 'tablet' },
  { width: 1440, height: 900, name: 'desktop' },
  { width: 1440, height: 2000, name: 'tall desktop' },
]) {
  const ctx = await browser.newContext({ viewport: { width: vp.width, height: vp.height } })
  const page = await ctx.newPage()
  const reqs = new Set()
  page.on('request', (r) => { if (r.url().includes('/_next/image')) reqs.add(r.url()) })
  await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(4000)
  const state = await page.evaluate(() => {
    const boxes = [...document.querySelectorAll('a[href^="/products/"] > div > div')]
    let aboveFold = 0
    let aboveFoldEmpty = 0
    boxes.forEach((box) => {
      const r = box.getBoundingClientRect()
      if (!(r.top < window.innerHeight && r.bottom > 0)) return
      aboveFold += 1
      const img = box.querySelector('img')
      const painted = img && img.complete && img.naturalWidth > 0
      if (!painted) aboveFoldEmpty += 1
    })
    return { total: boxes.length, aboveFold, aboveFoldEmpty }
  })
  console.log(
    `${vp.name.padEnd(13)} ${String(vp.width).padStart(4)}x${vp.height}: ` +
    `${String(reqs.size).padStart(2)} requests | ${state.aboveFold} cards above fold, ` +
    `${state.aboveFoldEmpty} still empty after 4s`,
  )
  await ctx.close()
}

// --- measured contrast, from painted sRGB ---
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const page = await ctx.newPage()
await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' })
const result = await page.evaluate((resolveSrc) => {
  const resolve = eval(resolveSrc)
  const lum = ([r, g, b]) =>
    [r, g, b]
      .map((v) => {
        const c = v / 255
        return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)
      })
      .reduce((acc, c, i) => acc + [0.2126, 0.7152, 0.0722][i] * c, 0)
  const ratio = (a, b) => {
    const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x)
    return Number(((hi + 0.05) / (lo + 0.05)).toFixed(2))
  }
  const box = document.querySelector('a[href^="/products/"] > div > div')
  const placeholder = resolve(getComputedStyle(box).backgroundColor)

  // The two alternating category bands, resolved through whatever ancestor
  // actually paints (bg-inherit paints nothing of its own).
  const bands = [...document.querySelectorAll('main > div')].slice(2, 4).map((el) => {
    let node = el
    let bg = getComputedStyle(node).backgroundColor
    while ((bg === 'rgba(0, 0, 0, 0)' || bg === 'transparent') && node.parentElement) {
      node = node.parentElement
      bg = getComputedStyle(node).backgroundColor
    }
    return resolve(bg)
  })
  return { placeholder, bands, ratios: bands.map((b) => ratio(placeholder, b)) }
}, RESOLVE)

console.log(`\nplaceholder sRGB rgb(${result.placeholder.join(', ')})`)
result.bands.forEach((b, i) =>
  console.log(`  vs band ${i + 1} rgb(${b.join(', ')}): ${result.ratios[i]}:1`),
)

await browser.close()

